import{_ as t}from"./chunks/gather-evidence.CFBdlZLj.js";import{_ as a}from"./chunks/test-case-detail.C5uQxYLf.js";import{_ as o,o as r,c as s,ak as n}from"./chunks/framework.sV-XtlWr.js";const w=JSON.parse('{"title":"Failure evidence","description":"","frontmatter":{"title":"Failure evidence","lang":"en-US"},"headers":[],"relativePath":"features/evidence.md","filePath":"features/evidence.md","lastUpdated":1788707541000}'),i={name:"features/evidence.md"};function h(d,e,l,c,g,u){return r(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="failure-evidence" tabindex="-1">Failure evidence <a class="header-anchor" href="#failure-evidence" aria-label="Permalink to &quot;Failure evidence&quot;">​</a></h1><p>When a test fails, everything Piwi captured about that attempt lands on one screen. This page describes that screen — what each block holds, where the data came from, and how much more you get once a trace is attached.</p><p>Two different pages are involved, and <a href="/concepts.html#execution">Core concepts</a> draws the line between them:</p><table tabindex="0"><thead><tr><th>Page</th><th>Path</th><th>Answers</th></tr></thead><tbody><tr><td><strong>Execution</strong></td><td><code>/test-run-cases/:id</code></td><td>&quot;why did this attempt fail?&quot; — <a href="#one-execution-diagnosis-first">the diagnosis view</a></td></tr><tr><td><strong>Test case</strong></td><td><code>/test-cases/:id</code></td><td>&quot;how has this test behaved over time?&quot; — <a href="#the-test-case-page">its history</a></td></tr></tbody></table><p>Most links from a run land on an execution; the test&#39;s title links to the test case above it.</p><h2 id="one-execution-diagnosis-first" tabindex="-1">One execution, diagnosis-first <a class="header-anchor" href="#one-execution-diagnosis-first" aria-label="Permalink to &quot;One execution, diagnosis-first&quot;">​</a></h2><p>Everything about a single test execution in <strong>one column, read top to bottom</strong>: what happened, why, the evidence, then what to do. The page <strong>header</strong> carries the status, title, the exceptional badges only (new regression, passed on retry, newly flaky, Playwright marks such as <code>@fixme</code> / <code>@slow</code>, quarantined) and the primary action <strong>Copy retry command</strong>; under it, one line of facts — the failing file and line (open-in-IDE), browser and viewport, duration with its average and delta, the attempts, branch and commit, the CI build, and when it started — with a <strong>Details</strong> popover holding the rest (CI provider, workflow and job, environment, Playwright and Piwi versions, worker, shard, step count, slowest step, wasted time, tags, links). Traces stream in live while the parent run is still running.</p><figure><img src="'+t+'" alt="A failing execution: the header, the one-line headline with its strongest clue, the other clues, then one evidence card whose tabs — Timeline, Screen, Source, Network, Console, State, Performance — hold the captured evidence"><figcaption>A failing execution — the header, the headline with its strongest clue, the other clues, and one evidence card whose tabs hold everything captured.</figcaption></figure><p>Below the header the reading order is the same every time: the <strong>headline</strong>, the <strong>other clues</strong>, one <strong>evidence</strong> card, then the <strong>Fix</strong> card and the <strong>history</strong>.</p><ul><li><p><strong>Headline</strong> — what broke, in one sentence built from the Playwright error itself, before you read a line of it: <code>getByRole(&#39;button&#39;, { name: &#39;Pay&#39; }) never became enabled — click timed out after 30 s</code>, <code>Expected 26 rows, found 51 — getByRole(&#39;row&#39;) toHaveCount</code>, <code>Text &quot;Invite sent&quot; never became visible (30 s)</code>, <code>Navigation to /users timed out after 30 s</code>, <code>getByRole(&#39;button&#39;) matched 3 buttons — strict mode</code>, <code>Test timed out after 30 s while &quot;fillPaymentDetails(page)&quot;</code>. The parser reads the action or matcher, the locator, the expected and received values, the timeout and the last state Playwright&#39;s call log reported (not found, hidden, not enabled, covered by another element, N elements, navigating); a shape it does not know falls back to the error&#39;s first line. Under it, one row of facts: <strong>why</strong> (new regression, passed on retry, new flaky, infrastructure), <strong>since when</strong> (the first run the cluster failed in, the commit and author the run reported), how many <strong>other tests in this run</strong> share the cause and the cluster&#39;s triage status, and the <strong>owner</strong> (<code>piwi:owner</code> annotation first, then CODEOWNERS when an SCM token is configured). At the bottom of the card, <strong>Show raw error</strong> is a disclosure — collapsed to the first error line, one click from the verbatim ANSI-rendered error and a <strong>Copy failure</strong> action. The same headline names every failing row on the run page, leads the <a href="./notifications.html">alerts</a> and the <a href="/ci.html#pull-request-feedback">pull-request comment</a>, reaches AI agents through the MCP tools, and is what the <a href="/reporter.html#how-it-works">reporter prints</a> next to each failing test in the terminal — the raw error is never rewritten, only preceded.</p></li><li><p><strong>Clues</strong> — the strongest <a href="#clues">deterministic clue</a> in one line right on the headline (<em>&quot;GET /api/quote returned 504, 1.1 s before the failure&quot;</em>), with an <strong>Other clues</strong> card below listing the rest, each with a strength chip, its <code>t-N s</code> before the failure, and citation chips that switch to the evidence tab it came from and scroll to it.</p></li><li><p><strong>Evidence</strong> — one card with content-level tabs; each tab shows a count or a dot when it holds data and is dimmed when empty, and a dimmed tab still opens to say why (not captured / nothing happened / not applicable). The card opens on the tab the strongest clue cites, else the <strong>Timeline</strong> when it can place two or more items, else <strong>Screen</strong> — and a clue or diagnosis citation switches tabs for you:</p><ul><li><strong>Timeline</strong> — one time axis that places the <strong>steps</strong>, <strong>console</strong> entries, <strong>network</strong> requests and their <strong>backend logs</strong> — and, on Playwright 1.63+, any <strong>browser dialogs</strong> that were open — on the same clock and marks the <strong>moment of failure</strong>, so &quot;console (1) / network (3)&quot; become <em>what the app was doing when the test gave up</em>. Below the axis sits <strong>one steps table</strong>: each step carries its offset from the failure (<code>t-1.1s</code>), its category, its label (the failed step in red with its error), and its duration with the share of the test and a bar; the label shows the step title, then its target — the rendered locator, or the navigation URL that Playwright 1.63+ carries as a separate subtitle — in a muted second element on the same row, so <code>Click</code> reads first and <code>getByRole(&#39;button&#39;, { name: &#39;Pay&#39; })</code> follows it after an upgrade; a step that carries curated <strong>params</strong> (the locator, a navigation&#39;s full URL, an action&#39;s value, or a <code>test.step</code> author&#39;s own values) shows a <strong>Parameters</strong> disclosure you open on demand, the locator first; the network, console and backend items in the window are interleaved as their own rows in time order, so the table <em>is</em> what happened. Two views, <strong>Around the failure</strong> and <strong>Whole test</strong>, drive both the axis and the table — window rows only, or every step. A passing execution has no failure moment, so the axis is hidden and the table lists every step without offsets. Web Vitals and screenshots carry no capture time, so they are listed as not-yet-placed rather than guessed at.</li><li><strong>Attempts</strong> — shown when a test ran more than once (it failed then passed on retry): every attempt with its status and duration, and below them <a href="#attempts">what differed</a> between the failing attempt and the one that passed.</li><li><strong>Screen</strong> — the failure screenshot, the <strong>visual diff</strong> against the last green run, video, the failure-time <strong>ARIA snapshot</strong>, the reconstructed <strong>DOM snapshot</strong> with pick-a-locator, and the trace and attachments.</li><li><strong>Source</strong> — the <strong>test source</strong> as a call stack (the line that actually threw plus the callers above it, so a failure inside a helper is visible), deepening <a href="#trace-powered-deep-views">with a trace</a> into the complete stack with real source.</li><li><strong>Network</strong> — the <strong>network requests</strong> with inline <a href="/backend-logs.html">backend logs</a> and a <a href="#trace-powered-deep-views">Full trace</a> network view. <strong>Console</strong> — the console output. <strong>State</strong> — the <strong>app state</strong> at test end and the <strong>environment diff</strong> against the last green run. <strong>Performance</strong> — performance hints, Web Vitals, the slowest step and wasted time.</li></ul></li></ul><p>Below the evidence sit the <strong>Fix</strong> card and the <strong>history</strong>. The Fix card gathers what to do about the failure, each part shown only when it applies: the <strong>locator fix</strong> (<a href="./locator-healing.html">alternative locators</a> for a broken locator, provenance first), a <strong>fix plan</strong> pointer to the cluster page, the <strong>diagnosis</strong> (the cluster&#39;s <a href="./ai-diagnosis.html">AI diagnosis</a> summary, else this execution&#39;s own — or one line when no provider is configured, never a placeholder block), <strong>verify</strong> (re-run in CI, or run locally in the desktop shell), and the tests this failure <strong>blocked</strong>. The <strong>history</strong> block is a strip of this test&#39;s recent executions, each linking to its execution, with the failing-streak sentence and a link to the full <a href="#one-execution-diagnosis-first">test history</a>.</p><h3 id="clues" tabindex="-1">Clues <a class="header-anchor" href="#clues" aria-label="Permalink to &quot;Clues&quot;">​</a></h3><p>A <strong>clue</strong> is a deterministic, rule-based finding correlated from the evidence already captured — no model runs. A small library of rules looks at the parsed error, the timeline, the network requests, the ARIA snapshot, the locator-healing result, the app state, the environment diff, the run&#39;s sibling and same-worker executions, and the cluster&#39;s fix history, and each rule that fires emits a ranked, cited one-line clue. Every clue carries a <strong>strength</strong> (strong / medium / weak) and a <strong>citation</strong> to the evidence section it came from — the same section ids the AI diagnosis cites — so a click jumps straight to the proof, and the same clues are handed to the AI diagnosis as evidence to confirm or refute (and used to prioritize the <a href="./ai-diagnosis.html#enabling-ai-diagnosis">auto-diagnose budget</a>). The rules:</p><ul><li><strong>Failed request before the failure</strong> <em>(strong)</em> — a request returned 5xx or was aborted within the lead window before the moment of failure.</li><li><strong>Slow request overlapping the failure</strong> <em>(medium)</em> — a request slower than the slow-request threshold was still in flight during the failed step.</li><li><strong>Console mentions the target</strong> <em>(strong for an error, medium for a warning)</em> — a console entry in the failure window names the failing locator or the failing route.</li><li><strong>Backend error attached</strong> <em>(strong)</em> — a request in the window carries an error-level <a href="/backend-logs.html">backend log</a>.</li><li><strong>Element renamed</strong> <em>(strong)</em> — locator healing found the element under a new identity, or flagged the stored name as stale while still recommending a fix.</li><li><strong>Page structure changed near the failing locator</strong> <em>(strong)</em> — the <a href="#page-diff">page diff</a> against the last green sample shows the element the locator names was removed or renamed since the test last passed.</li><li><strong>Element present but blocked</strong> <em>(strong)</em> — the call log says the element resolved but was disabled, hidden, not visible or covered, and the ARIA snapshot still shows one with its role and name.</li><li><strong>Dialog open at the failure</strong> <em>(strong)</em> — a browser dialog (<code>alert</code>/<code>confirm</code>/<code>prompt</code>/<code>beforeunload</code>) closed around the moment of failure, so it was open when the action ran. A native dialog blocks the page until dismissed, so the action could not proceed. Needs Playwright 1.63+ (the reporter observes dialogs through the <code>dialogclosed</code> event).</li><li><strong>Wrong page</strong> <em>(strong)</em> — the page ended on a login, auth, error or 404 route, or somewhere other than the last navigation the test asked for. Where it ended is read from the captured app-state URL, falling back to the last navigation step&#39;s own <code>params.url</code> when no app state was captured.</li><li><strong>Worker pollution</strong> <em>(medium)</em> — the previous test on this worker failed or timed out, so shared state it left behind is a candidate cause.</li><li><strong>Previous lock holder failed</strong> <em>(strong)</em> — the execution that held the same <a href="/reporter.html#test-locks">lock</a> just before this test, in this run, failed or timed out — a named shared resource, stronger than worker pollution because the resource is named.</li><li><strong>Lock held on two shards</strong> <em>(medium)</em> — a lock this test held overlapped in wall-clock time with a holder on a different shard. Locks serialize only within one <code>playwright test</code> process, so sharded runs never coordinate — the classic &quot;passes on one machine&quot; flake.</li><li><strong>Timeout budget</strong> <em>(medium)</em> — the failed step used ≥ 80 % of the test timeout, or the execution used ≥ 95 % of it.</li><li><strong>Environment changed</strong> <em>(medium, weak when only the environment label differs)</em> — the same-environment <a href="#one-execution-diagnosis-first">environment diff</a> is non-empty.</li><li><strong>Browser-specific</strong> <em>(medium)</em> — the same test passed on at least one other browser in this run.</li><li><strong>Fixed before</strong> <em>(weak)</em> — this cluster recorded a fix that has since regressed.</li></ul><p>The card is hidden when no rule fires, and the ranked list is capped at eight clues.</p><h3 id="attempts" tabindex="-1">Attempts <a class="header-anchor" href="#attempts" aria-label="Permalink to &quot;Attempts&quot;">​</a></h3><p>When a test failed and then passed on retry, the <strong>Attempts</strong> tab compares the failing attempt against the one that passed — the flakiness fingerprint, computed from evidence Piwi already stores for each attempt. It lists every attempt (its status and duration, with the one you opened marked), then <strong>what differed</strong>, most-diagnostic first:</p><ul><li>the <strong>error</strong> that was present on the failing attempt and gone on the pass;</li><li>a <strong>request</strong> that failed (5xx or no response) on one attempt but not the other;</li><li>a <strong>console</strong> error or warning logged on only one attempt;</li><li>a <strong>step</strong> that errored, ran much slower, or ran with different <strong>params</strong> (a URL, a value, a <code>test.step</code> input) on one attempt;</li><li>a <strong>duration</strong> delta between the two attempts;</li><li>a <strong>page-state or URL</strong> difference — where the page ended, and which storage keys or cookies each attempt held;</li><li>an <strong>ARIA structural</strong> difference at the landmark/heading level.</li></ul><p>Each difference is labeled by the attempt it sits on (<em>only on the failing attempt</em> / <em>only on the passing attempt</em> / <em>changed</em>) and carries a chip that switches to the evidence tab it came from. That same delta feeds the <a href="./flaky-tests.html#root-cause-classification">root-cause classifier</a>: a request that failed on the failing attempt and recovered on the pass is strong evidence the flakiness is a network problem.</p><p><strong>A passing execution shows the same page</strong> with the evidence card&#39;s <strong>Timeline</strong> tab selected; its traces, attachments, console and network are in the same tabs a failing execution uses.</p><p>Both keep a <strong>Performance</strong> tab in the evidence card (performance hints plus color-coded <strong>Web Vitals</strong>) and the <strong>history</strong> block below it (this test&#39;s recent executions as a strip, linking through to the full test history). A <strong>Copy retry command</strong> button in the header gives you the exact Playwright command to re-run just this test. The Web Vitals, network, console, ARIA-snapshot and alternative-locator data all come from the <a href="/capture-fixtures.html">capture fixtures</a>.</p><h2 id="page-diff" tabindex="-1">Page diff <a class="header-anchor" href="#page-diff" aria-label="Permalink to &quot;Page diff&quot;">​</a></h2><p>The <strong>Screen</strong> tab carries a <strong>Screenshot · Page diff</strong> toggle. Where the visual diff compares pixels, the page diff compares <em>structure</em>: it parses the failing page&#39;s <a href="/reporter.html#what-gets-captured">ARIA snapshot</a> and the same test&#39;s last passing (green) snapshot into trees and reports what changed between them — nodes <strong>added</strong>, <strong>removed</strong>, <strong>renamed</strong> (same role and place, a different accessible name), <strong>changed</strong> (an attribute like <code>[disabled]</code> flipped) or <strong>moved</strong> — with unchanged subtrees collapsed and a compact <code>+3 −1 ~2</code> summary. The element the failing locator names is highlighted, so a broken <code>getByRole(&#39;button&#39;, { name: &#39;Pay&#39; })</code> lands you on the line proving the button became <code>&quot;Pay now&quot;</code>. The baseline is stated in one line (<em>vs last green — run #123 on <code>abc1234</code>, 2 days ago</em>).</p><p>The baseline follows the same rule as the <a href="#trace-powered-deep-views">visual</a> and <a href="#one-execution-diagnosis-first">environment</a> diffs: the same test&#39;s most recent passing execution that carries a snapshot, on the same browser, preferring the same environment then the same branch.</p><p>Green snapshots come from <strong>sampling on pass</strong>: the <a href="/reporter.html#green-page-sampling-on-pass">reporter</a> captures a passing page&#39;s ARIA snapshot about once a day per test (rate-limited by the server, so steady-state runs pay nothing). Until the first one lands, the toggle is replaced by the three-state empty copy: <em>not captured</em> (the fixtures are off), <em>no green sample yet</em> (a baseline appears after the next passing run), or <em>not applicable</em>. The page-diff summary also rides the <a href="/mcp.html"><code>explain_failure</code></a> MCP tool, so an agent sees the structural change too.</p><p>When the trace carries <a href="#aria-and-screen-snapshots">aria snapshots</a> (Playwright 1.63+), the toggle also shows an <strong>in-execution</strong> page diff that needs no green baseline: it compares the page structure <em>at the failure</em> against the last page <em>before the failing action</em> that differs from it — isolating the change that led to the failure, the button that got disabled or the row that vanished, from this run alone. It sits above the vs-green diff, and the toggle appears whenever either has something to show.</p><h2 id="trace-powered-deep-views" tabindex="-1">Trace-powered deep views <a class="header-anchor" href="#trace-powered-deep-views" aria-label="Permalink to &quot;Trace-powered deep views&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Screenshots are Playwright&#39;s to record</p><p>The screenshots in <strong>failure evidence</strong> come from Playwright&#39;s <code>screenshot: &#39;only-on-failure&#39;</code> <code>use</code> option (<code>&#39;on&#39;</code> records every test). Playwright&#39;s default is <code>&#39;off&#39;</code>, so with the option unset the block shows video and traces but no screenshot. Set it beside <code>trace</code> in your Playwright config; see <a href="/reporter.html#basic-configuration">Basic configuration</a> on the reporter page.</p></div><p>When an execution has an uploaded trace, two evidence blocks go deeper — no configuration beyond recording traces (<code>trace: &#39;retain-on-failure&#39;</code> or <code>&#39;on-first-retry&#39;</code> in your Playwright config):</p><ul><li><strong>Test source → Full stack</strong> — the complete call stack of the failing action from the trace&#39;s stacks index, every frame with its real source read from the trace&#39;s embedded files (recorded by default with the Playwright test runner), the failing line highlighted, dependency frames folded, and Open-in-IDE links on each in-project frame. A toggle switches back to the reporter-captured frames.</li><li><strong>Network → Full trace</strong> — every request the page made (documents, scripts, images — not just fetch/XHR), on a waterfall with the failing action&#39;s time window shaded. Click a request for timing phases, request/response headers, and a capped body preview (JSON pretty-printed, images inline). Sensitive header values (<code>Authorization</code>, <code>Cookie</code>, …) are masked server-side and never leave the dashboard, and token-shaped strings in URLs and bodies are masked too.</li></ul><p>Executions without a trace keep the reporter-captured baseline — the blocks simply hint at what a trace would add. Traces recorded without embedded sources still show the full frame list.</p><h3 id="aria-and-screen-snapshots" tabindex="-1">Aria and screen snapshots <a class="header-anchor" href="#aria-and-screen-snapshots" aria-label="Permalink to &quot;Aria and screen snapshots&quot;">​</a></h3><p>A Playwright 1.63 trace can record the page&#39;s <strong>aria tree</strong> and a <strong>screenshot</strong> before and after every action (<code>trace: { snapshots: { dom, aria, screen } }</code>; <a href="/reporter.html#installing-via-wrapconfig"><code>wrapConfig</code></a> turns <code>aria</code> on by default, <code>screen</code> stays <a href="/operate/storage.html#trace-snapshots">opt-in</a>). When it did, two more views appear:</p><ul><li><strong>Screen tab › Before the failing action</strong> — the page as the failing action saw it, before and at the failure, beside the failure screenshot.</li><li><strong>Timeline tab › the filmstrip</strong> — a thumbnail of the page <em>before each step</em>, in order, the failing step marked. It turns the step list into a visual scrub of how the page looked on the way to the failure, and needs only <code>screen</code>.</li></ul><p>The <a href="#page-diff">in-execution page diff</a> reads the same aria snapshots. All three states use the three-state empty copy (<em>not captured — enable trace snapshots</em>, with the <code>/setup</code> link) when the trace predates 1.63 or was recorded without the kind.</p><h3 id="recovered-from-the-trace-without-the-fixtures" tabindex="-1">Recovered from the trace without the fixtures <a class="header-anchor" href="#recovered-from-the-trace-without-the-fixtures" aria-label="Permalink to &quot;Recovered from the trace without the fixtures&quot;">​</a></h3><p>A project that installed only the reporter — no <a href="/capture-fixtures.html">capture fixtures</a> — still gets most of the failure evidence, because the trace carries it. When a reported execution has an uploaded trace but no fixture data, the dashboard recovers three things at ingest and stores them in the same place the fixtures would: the <strong>console</strong> entries (<code>warning</code>/<code>error</code>/<code>assert</code>), the <strong>network requests</strong> (method, URL, status, duration, start time — restricted to the API and document requests the fixtures keep, and including the failed and aborted requests the fixtures never captured), and the failure-time <strong>ARIA snapshot</strong> — from an <code>error-context</code> Playwright wrote alongside the trace, or, on a 1.63 trace recorded with <a href="#aria-and-screen-snapshots">aria snapshots</a>, from the failing action&#39;s own before-page tree. Cards showing this data carry a <strong>derived from the trace</strong> chip. Fixture-captured data is never replaced, and each kind is recovered only when it is otherwise missing. This is on by default with <a href="/reporter.html#installing-via-wrapconfig"><code>wrapConfig</code></a>, which records the trace for you.</p><h3 id="why-a-card-is-empty" tabindex="-1">Why a card is empty <a class="header-anchor" href="#why-a-card-is-empty" aria-label="Permalink to &quot;Why a card is empty&quot;">​</a></h3><p>Console, network, app state, ARIA snapshot, backend logs and Web Vitals no longer simply vanish when they hold nothing. Each empty card states exactly one of three things, so a blank block is never ambiguous:</p><ul><li><strong>Not captured</strong> — the <a href="/capture-fixtures.html">capture fixtures</a> are not active for this project (for example a spec that still imports <code>test</code> from <code>@playwright/test</code>). The card names what to add and links to the in-app <code>/setup</code> capability checklist. &quot;Fixtures active&quot; is decided per execution, so a spec that never adopted the fixtures reads <em>not captured</em> while its fixture-using neighbors read <em>nothing happened</em>.</li><li><strong>Captured, nothing happened</strong> — the fixtures were active and this run simply produced nothing (no console output, no matching requests, …). Working as intended, nothing to fix.</li><li><strong>Not applicable</strong> — the card needs a capability the app under test does not have. Backend logs are the case: they need a <a href="/backend-logs.html">Piwi backend integration</a> on the app under test on top of the fixtures.</li></ul><p>The AI diagnosis reads the same map: its <strong>Data Coverage</strong> block names each absent section with the same reason a human sees, so the model and the reader are never looking at different pictures.</p><h2 id="trace-viewer" tabindex="-1">Trace viewer <a class="header-anchor" href="#trace-viewer" aria-label="Permalink to &quot;Trace viewer&quot;">​</a></h2><p>Every trace shows a <strong>View trace</strong> button that opens the full Playwright trace viewer — the same UI as <code>npx playwright show-trace</code>, with the DOM snapshot timeline, action log, network, console, and source.</p><p>The viewer is <strong>served by the dashboard itself</strong> (the <code>playwright-core</code> viewer assets are bundled and served at <code>/trace-viewer/</code>), so traces are never uploaded to a third party — unlike sending a colleague to <code>trace.playwright.dev</code>, the bytes stay on your server. Traces are stored efficiently: each archive is split into a slim events ZIP plus a project-wide, hash-deduplicated resource pool, and reconstructed on download (see <a href="/operate/storage.html">Storage</a>). Trace blobs are content-addressed, so the browser caches them and re-opening a trace is instant.</p><div class="tip custom-block"><p class="custom-block-title">Authentication caveat</p><p>The bundled <code>/trace-viewer/</code> is same-origin, so it works whether or not <a href="/operate/authentication.html">authentication</a> is enabled. The hosted <code>trace.playwright.dev</code> viewer is a different origin and cannot send your session cookie, so it only works against a dashboard with auth disabled — use the built-in <strong>View trace</strong> button, which always works.</p></div><h2 id="the-test-case-page" tabindex="-1">The test case page <a class="header-anchor" href="#the-test-case-page" aria-label="Permalink to &quot;The test case page&quot;">​</a></h2><p><code>/test-cases/:id</code> is the other axis: not one attempt, but the test&#39;s whole life. Total runs, pass rate, average duration and last run across every execution, a duration trend, a status-history strip, and the list of recent executions — each linking back to the diagnosis view above.</p><figure><img src="'+a+'" alt="Test case page with total runs, pass rate, failed count, average duration, flaky count and last run, above a duration trend chart, a status history strip, and a table of recent executions"><figcaption>The test case page — the across-time view: pass rate and duration stats, a duration trend, a status-history strip, and every recent execution of this one test.</figcaption></figure><h2 id="taking-it-out-of-the-dashboard" tabindex="-1">Taking it out of the dashboard <a class="header-anchor" href="#taking-it-out-of-the-dashboard" aria-label="Permalink to &quot;Taking it out of the dashboard&quot;">​</a></h2><p>Any of this can leave the dashboard as a self-contained file — for a ticket attachment, a colleague without an account, or an archive that outlives your retention window. See <a href="./offline-export.html">Offline export</a>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/capture-fixtures.html">Capture fixtures</a> — the one file that produces the network, console, Web Vitals and locator evidence</li><li><a href="./ai-diagnosis.html">AI diagnosis &amp; clustering</a> — the same investigation across every test sharing a fingerprint</li><li><a href="/concepts.html#execution">Core concepts</a> — execution versus test case</li><li><a href="/recipes/broken-locator.html">Fix a broken locator</a> — this page, used for one concrete job</li></ul>',52)])])}const b=o(i,[["render",h]]);export{w as __pageData,b as default};
